-- Cellier migration 04: inventory. Pantries, categories, products, stock (cache) and the
-- append-only stock movement ledger.
--
-- Tenant safety: children reference (household_id, parent_id) through composite foreign keys,
-- so a row can never point at another household's pantry, category or product. Each parent has
-- unique (household_id, id), which also serves "all rows of a household" scans.
-- Ids of pantries, categories, products and movements are generated by the client (UUID v4)
-- so that optimistic rows keep their identity after sync.

create table public.pantries (
  id           uuid primary key,
  household_id uuid not null references public.households (id) on delete cascade,
  name         text not null check (char_length(btrim(name)) between 1 and 60),
  name_key     text generated always as (private.normalize_name(name)) stored,
  icon         text check (icon is null or char_length(icon) <= 40),     -- design icon key; null = default
  color        text check (color is null or char_length(color) <= 24),   -- design colour token; null = default
  sort_order   integer not null default 0,
  field_clock  jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,                                               -- tombstone
  unique (household_id, id),
  unique (household_id, name_key)                                         -- natural key, tombstones included
);

-- Household categories. Seeded from category_templates when the household is created;
-- template_key keeps the link to the default (icon/colour default and catalogue mapping).
create table public.categories (
  id           uuid primary key,
  household_id uuid not null references public.households (id) on delete cascade,
  template_key text references public.category_templates (key) on update cascade on delete set null,
  name         text not null check (char_length(btrim(name)) between 1 and 60),
  name_key     text generated always as (private.normalize_name(name)) stored,
  icon         text check (icon is null or char_length(icon) <= 40),
  color        text check (color is null or char_length(color) <= 24),
  sort_order   integer not null default 0,
  field_clock  jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (household_id, id),
  unique (household_id, name_key),
  unique (household_id, template_key)       -- nulls are distinct: any number of custom categories
);
create index categories_template_key_idx on public.categories (template_key);

-- Household products. Values are copied from the catalogue when the product is created and can
-- then be edited freely; the household row is the source of truth for display.
create table public.products (
  id           uuid primary key,
  household_id uuid not null references public.households (id) on delete cascade,
  name         text not null check (char_length(btrim(name)) between 1 and 200),
  name_key     text generated always as (private.normalize_name(name)) stored,
  brand        text check (brand is null or char_length(brand) <= 120),
  gtin         text check (gtin is null or gtin ~ '^[0-9]{14}$'),          -- scanned barcode, if any
  catalog_gtin text references public.catalog_products (gtin) on update cascade on delete set null,
  category_id  uuid,
  net_quantity numeric(12, 3) check (net_quantity is null or net_quantity > 0),
  net_unit     text check (net_unit in ('g', 'ml', 'piece')),
  pack_count   smallint check (pack_count is null or pack_count between 1 and 999),
  price_cents  integer check (price_cents is null or price_cents between 0 and 10000000),
  price_source text check (price_source in ('catalog', 'user')),
  min_quantity integer check (min_quantity is null or min_quantity between 0 and 9999),  -- seuil; null = default rule
  usual_quantity integer check (usual_quantity is null or usual_quantity between 1 and 9999), -- purchase size override; null = forecast
  low_alert    boolean not null default true,                                           -- false = never "running low"
  image_url    text check (image_url is null or char_length(image_url) <= 500),
  field_clock  jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (household_id, id),
  unique (household_id, gtin),              -- natural key for scanned products (tombstones included)
  foreign key (household_id, category_id)
    references public.categories (household_id, id) on delete set null (category_id)
);
-- Natural key for products without a barcode.
create unique index products_custom_name_key_idx
  on public.products (household_id, name_key) where gtin is null;
-- Foreign key indexes.
create index products_category_id_idx on public.products (household_id, category_id);
create index products_catalog_gtin_idx on public.products (catalog_gtin);

-- Stock cache: quantity of one product in one pantry. Written ONLY by the ledger triggers.
create table public.stock (
  household_id uuid not null,
  pantry_id    uuid not null,
  product_id   uuid not null,
  quantity     integer not null default 0 check (quantity >= 0),   -- the server-side floor
  updated_at   timestamptz not null default now(),
  primary key (household_id, pantry_id, product_id),
  foreign key (household_id, pantry_id) references public.pantries (household_id, id) on delete cascade,
  foreign key (household_id, product_id) references public.products (household_id, id) on delete cascade
);
-- Per-product totals across pantries (running-low check) and the product FK.
create index stock_product_idx on public.stock (household_id, product_id);

-- Append-only ledger. One row per applied stock action. The id is the client mutation id
-- (the in-leg of a transfer gets a server-generated id).
create table public.stock_movements (
  id              uuid primary key,
  seq             bigint generated always as identity unique,   -- server apply order
  household_id    uuid not null,
  pantry_id       uuid not null,
  product_id      uuid not null,
  kind            text not null check (kind in
                    ('restock', 'consume', 'discard', 'recount', 'transfer_out', 'transfer_in', 'correction')),
  counted         integer check (counted is null or counted >= 0),  -- recount only: the counted quantity
  requested_delta integer not null,
  applied_delta   integer not null,
  clamped         boolean generated always as (applied_delta <> requested_delta) stored,
  quantity_after  integer not null check (quantity_after >= 0),    -- pantry quantity after this movement
  transfer_id     uuid,                                            -- links the two legs of a move
  reverts_id      uuid references public.stock_movements (id),     -- correction: the movement it undoes
  actor_id        uuid references auth.users (id) on delete set null,
  device_id       uuid,
  client_at       timestamptz,                                      -- when the user acted (informational)
  source          text check (source is null or source in ('scan', 'swipe', 'stepper', 'put_away', 'form', 'undo')),
  created_at      timestamptz not null default now(),               -- when the server applied it
  check ((kind = 'recount') = (counted is not null)),
  check (kind = 'recount' or requested_delta <> 0),
  check (kind not in ('restock', 'transfer_in') or requested_delta > 0),
  check (kind not in ('consume', 'discard', 'transfer_out') or requested_delta < 0),
  check (applied_delta = 0 or sign(applied_delta) = sign(requested_delta)),
  check ((kind = 'correction') = (reverts_id is not null)),
  foreign key (household_id, pantry_id) references public.pantries (household_id, id) on delete cascade,
  foreign key (household_id, product_id) references public.products (household_id, id) on delete cascade
);
-- Snapshot window and activity feed: household, newest first.
create index stock_movements_household_created_idx on public.stock_movements (household_id, created_at desc);
-- Per-product history (forecasting, product detail) and the product FK.
create index stock_movements_product_idx on public.stock_movements (household_id, product_id, created_at desc);
-- Pantry FK.
create index stock_movements_pantry_idx on public.stock_movements (household_id, pantry_id);
-- Actor FK.
create index stock_movements_actor_id_idx on public.stock_movements (actor_id);
-- A movement can be reverted once; also the FK index for reverts_id.
create unique index stock_movements_reverts_id_idx on public.stock_movements (reverts_id);
-- Find both legs of a transfer.
create index stock_movements_transfer_id_idx on public.stock_movements (transfer_id) where transfer_id is not null;

-- Courses (shopping list). An entry is a product of the household or a free-text label.
-- Checking an entry never changes stock (put-away is a separate stock.add). Running-low products are
-- suggested by the client without a row; dismissing a suggestion stores an entry with dismissed_at.
create table public.grocery_entries (
  id           uuid primary key,                                   -- client-generated
  household_id uuid not null references public.households (id) on delete cascade,
  product_id   uuid,
  label        text check (label is null or char_length(btrim(label)) between 1 and 80),
  quantity     integer check (quantity is null or quantity between 1 and 999),  -- null = suggested quantity
  added_by     uuid references auth.users (id) on delete set null,
  checked_at   timestamptz,
  checked_by   uuid references auth.users (id) on delete set null,
  dismissed_at timestamptz,
  field_clock  jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  check ((product_id is null) <> (label is null)),
  unique (household_id, id),
  foreign key (household_id, product_id) references public.products (household_id, id) on delete cascade
);
-- Natural key: one open entry per product (add-versus-add merges into it).
create unique index grocery_entries_open_product_idx on public.grocery_entries (household_id, product_id)
  where product_id is not null and checked_at is null and dismissed_at is null and deleted_at is null;
-- Product FK.
create index grocery_entries_product_idx on public.grocery_entries (household_id, product_id);
-- Actor FKs.
create index grocery_entries_added_by_idx on public.grocery_entries (added_by);
create index grocery_entries_checked_by_idx on public.grocery_entries (checked_by);

-- Field-overwrite records: a value written by one device was replaced by a later write from another
-- device (design: «Modification remplacée»). Written by trigger only; synced; pruned after 30 days.
-- The client whose device id ends old_hlc shows the notice.
create table public.field_overwrites (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  entity       text not null check (entity in ('household', 'pantry', 'category', 'product', 'grocery')),
  row_id       uuid not null,
  field        text not null,                 -- mutation field name (camelCase), e.g. 'priceCents'
  old_value    jsonb,
  new_value    jsonb,
  old_hlc      text not null,
  new_hlc      text not null,
  actor_id     uuid references auth.users (id) on delete set null,   -- author of the new value
  created_at   timestamptz not null default now()
);
create index field_overwrites_household_created_idx on public.field_overwrites (household_id, created_at desc);
create index field_overwrites_actor_id_idx on public.field_overwrites (actor_id);

create trigger grocery_entries_set_updated_at before update on public.grocery_entries
  for each row execute function private.set_updated_at();
create trigger pantries_set_updated_at before update on public.pantries
  for each row execute function private.set_updated_at();
create trigger categories_set_updated_at before update on public.categories
  for each row execute function private.set_updated_at();
create trigger products_set_updated_at before update on public.products
  for each row execute function private.set_updated_at();
